"""results/selective/agentdrift.json → paper-arxiv/figures/table_agentdrift.tex"""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
S = json.load((ROOT / "results" / "selective" / "agentdrift.json").open())["summary"]
OUT = ROOT / "paper-arxiv" / "figures" / "table_agentdrift.tex"

st, tr = S["step"], S["trajectory"]
fl = st["flag_rate_by_label"]
pc = lambda x: f"{100 * x:.1f}"
L = [
    "% Generated by research/selective/agentdrift_table.py — do not edit by hand.",
    "\\begin{table}[t]", "\\centering\\small", "\\setlength{\\tabcolsep}{5pt}",
    "\\caption{Instruction provenance as a step-level detector on AgentDrift (task-disjoint test and validation "
    f"splits: {S['n_trajectories']:,} trajectories, {S['n_steps']:,} steps). Each trajectory is replayed through the shipping "
    "gateway as the SDK reports a live agent; a step is flagged when the pack blocks or holds it, before its observation "
    "is seen. Positive class is \\emph{hijacked}. The dataset's own baseline is a surface-feature logistic regression over "
    "the step. Per trajectory, an attacked trajectory counts as caught when any hijacked step is flagged; a clean one "
    "counts as a false alarm when any step is.}",
    "\\label{tab:agentdrift}",
    "\\begin{tabular}{lrrr}", "\\toprule",
    "& Precision & Recall & F1 \\\\", "\\midrule",
    f"Per step, this layer & {pc(st['precision'])} & {pc(st['recall'])} & {pc(st['f1'])} \\\\",
    f"Per step, dataset baseline (reported) & --- & {pc(S['baseline_from_paper']['attack_recovery'])} & {pc(S['baseline_from_paper']['f1'])} \\\\",
    f"Per trajectory, this layer & {pc(tr['precision'])} & {pc(tr['recall'])} & {pc(tr['f1'])} \\\\",
    "\\midrule",
    "\\multicolumn{4}{l}{\\emph{Steps flagged, by the dataset's label}} \\\\",
]
for lab, nice in (("hijacked", "hijacked"), ("injection_point", "injection point (the call is the agent's own)"),
                  ("failed_injection", "failed injection (agent saw it, did not follow)"), ("benign", "benign")):
    v = fl[lab]
    L.append(f"\\quad {nice} & \\multicolumn{{3}}{{r}}{{{v['flagged']:,} of {v['n']:,} ({pc(v['rate'])}\\%)}} \\\\")
L += ["\\midrule", "\\multicolumn{4}{l}{\\emph{Attacked trajectories caught, by attack type}} \\\\"]
for k, v in S["trajectory_recall_by_attack_type"].items():
    if v["n"] >= 20:
        L.append(f"\\quad {k.replace('_', ' ')} & \\multicolumn{{3}}{{r}}{{{v['caught']} of {v['n']} ({pc(v['rate'])}\\%)}} \\\\")
cat = S["trajectory_flag_rate_by_category"]
L += ["\\midrule",
      f"Clean trajectories with a hold or block & \\multicolumn{{3}}{{r}}{{{tr['clean_trajectories_flagged']:,} of {tr['clean_trajectories']:,} ({pc(tr['clean_trajectories_flagged']/tr['clean_trajectories'])}\\%)}} \\\\",
      f"\\quad of which hard negatives & \\multicolumn{{3}}{{r}}{{{cat['hard_negative']['flagged']} of {cat['hard_negative']['n']} ({pc(cat['hard_negative']['rate'])}\\%)}} \\\\",
      "\\bottomrule", "\\end{tabular}", "\\end{table}"]
OUT.write_text("\n".join(L) + "\n")
print("wrote", OUT)
